  blogPostTag?: Prisma.BlogPostTagOmit
  contactMessage?: Prisma.ContactMessageOmit
  newsletterSubscriber?: Prisma.NewsletterSubscriberOmit
  quoteRequest?: Prisma.QuoteRequestOmit
  testDriveBooking?: Prisma.TestDriveBookingOmit
  dealership?: Prisma.DealershipOmit
  aboutPage?: Prisma.AboutPageOmit
  aboutStat?: Prisma.AboutStatOmit
  aboutGalleryImage?: Prisma.AboutGalleryImageOmit
  contactInfo?: Prisma.ContactInfoOmit
